import React, { useState, useEffect } from 'react';
import { useFleet }     from './hooks/useFleet';
import FleetMap         from './components/FleetMap';
import FleetList        from './components/FleetList';
import VehiclePanel     from './components/VehiclePanel';
import { IncidentLog, LatencyMeter } from './components/Telemetry';
import './App.css';

// ── Panel wrapper ─────────────────────────────────────────────────────────────
function Panel({ title, children, style }) {
  return (
    <div style={{ background:'rgba(255,255,255,0.015)', border:'1px solid rgba(255,255,255,0.07)',
      borderRadius:14, padding:14, display:'flex', flexDirection:'column', overflow:'hidden', ...style }}>
      {title && (
        <div style={{ fontSize:9, color:'#445566', textTransform:'uppercase', letterSpacing:2,
          marginBottom:10, flexShrink:0, display:'flex', alignItems:'center', gap:6 }}>
          <div style={{ width:2, height:9, background:'#00cfff', borderRadius:1 }} />{title}
        </div>
      )}
      <div style={{ flex:1, minHeight:0, overflow:'hidden' }}>{children}</div>
    </div>
  );
}

// ── Top bar ───────────────────────────────────────────────────────────────────
function TopBar({ stats, connected, latency }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => { const t = setInterval(() => setNow(new Date()), 1000); return () => clearInterval(t); }, []);

  return (
    <header style={{ display:'flex', alignItems:'center', justifyContent:'space-between',
      padding:'0 20px', height:56,
      borderBottom:'1px solid rgba(255,255,255,0.07)',
      background:'rgba(6,8,20,0.97)', flexShrink:0 }}>

      {/* Logo + title */}
      <div style={{ display:'flex', alignItems:'center', gap:14 }}>
        <div style={{ display:'flex', alignItems:'center', gap:9 }}>
          <div style={{ width:34, height:34, borderRadius:10,
            background:'linear-gradient(135deg, #ff6b35, #ff2244)',
            display:'flex', alignItems:'center', justifyContent:'center', fontSize:18,
            boxShadow:'0 0 16px #ff6b3544' }}>🚗</div>
          <div>
            <div style={{ fontSize:13, fontWeight:700, color:'#e0eaff', fontFamily:'monospace', letterSpacing:1 }}>
              EV FLEET CONTROL
            </div>
            <div style={{ fontSize:9, color:'#556677', fontFamily:'monospace', letterSpacing:2 }}>
              BANGALORE, INDIA · 12 REAL EVs
            </div>
          </div>
        </div>

        <div style={{ width:1, height:30, background:'rgba(255,255,255,0.08)' }} />

        {/* Live stats */}
        <div style={{ display:'flex', gap:20 }}>
          {[
            { label:'Moving',    value:stats.autonomous, color:'#00ff88' },
            { label:'Manual',    value:stats.manual,     color:'#ff6b35' },
            { label:'Charging',  value:stats.charging,   color:'#ffcc00' },
            { label:'Alerts',    value:stats.alerts,     color:'#ff2244' },
            { label:'Pax',       value:stats.totalPassengers, color:'#00cfff' },
            { label:'Avg Batt',  value:`${stats.avgBattery}%`, color:'#8899aa' },
          ].map((m) => (
            <div key={m.label}>
              <div style={{ fontSize:7, color:'#445566', textTransform:'uppercase', letterSpacing:1.2 }}>{m.label}</div>
              <div style={{ fontSize:16, fontWeight:700, color:m.color, fontFamily:'monospace' }}>{m.value}</div>
            </div>
          ))}
        </div>
      </div>

      {/* Right: clock + connection */}
      <div style={{ display:'flex', alignItems:'center', gap:16 }}>
        <div style={{ textAlign:'right' }}>
          <div style={{ fontSize:9, color:'#445566', fontFamily:'monospace' }}>
            {now.toLocaleDateString('en-IN', { weekday:'short', month:'short', day:'numeric' })}
          </div>
          <div style={{ fontSize:14, fontWeight:600, color:'#e0eaff', fontFamily:'monospace' }}>
            {now.toLocaleTimeString('en-IN')}
          </div>
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:6, padding:'5px 12px', borderRadius:20,
          background: connected ? 'rgba(0,255,136,0.07)' : 'rgba(255,34,68,0.1)',
          border:`1px solid ${connected ? '#00ff8830' : '#ff224430'}` }}>
          <div style={{ width:7, height:7, borderRadius:'50%',
            background: connected ? '#00ff88' : '#ff2244',
            boxShadow:`0 0 8px ${connected ? '#00ff88' : '#ff2244'}`,
            animation: connected ? 'pulse 2s infinite' : 'none' }} />
          <span style={{ fontSize:9, color: connected ? '#00ff88' : '#ff4466', fontFamily:'monospace', letterSpacing:1 }}>
            {connected ? `LIVE${latency ? ` · ${latency}ms` : ''}` : 'OFFLINE'}
          </span>
        </div>
      </div>
    </header>
  );
}

// ── App ───────────────────────────────────────────────────────────────────────
export default function App() {
  const { fleet, incidents, connected, latency, selectedVehicle, setSelectedVehicle,
    stats, takeover, release, clean, recall, deploy, sendCmd } = useFleet();

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100vh', width:'100vw', background:'#060812', overflow:'hidden' }}>
      <TopBar stats={stats} connected={connected} latency={latency} />

      {/* ── 3-column layout ── */}
      <div style={{ flex:1, display:'grid', gridTemplateColumns:'290px 1fr 300px', gap:10, padding:10, minHeight:0 }}>

        {/* LEFT — fleet list with car images */}
        <Panel title={`Fleet · ${fleet.length} Vehicles`}>
          <FleetList fleet={fleet} selectedVehicle={selectedVehicle} onSelect={setSelectedVehicle} />
        </Panel>

        {/* CENTRE — Bangalore map */}
        <div style={{ minHeight:0, borderRadius:14, overflow:'hidden', border:'1px solid rgba(255,255,255,0.07)' }}>
          <FleetMap fleet={fleet} selectedVehicle={selectedVehicle} onSelectVehicle={setSelectedVehicle} />
        </div>

        {/* RIGHT — vehicle detail + incidents */}
        <div style={{ display:'flex', flexDirection:'column', gap:10, minHeight:0 }}>
          <Panel title={selectedVehicle ? `${selectedVehicle.carName}` : 'Vehicle Details'} style={{ flex:1 }}>
            <div style={{ height:'100%', overflowY:'auto' }}>
              <VehiclePanel
                vehicle={selectedVehicle}
                onTakeover={takeover}
                onRelease={release}
                onClean={clean}
                onRecall={recall}
                onDeploy={deploy}
              />
            </div>
          </Panel>

          <Panel title="Incident Log" style={{ height:190, flexShrink:0 }}>
            <IncidentLog incidents={incidents} />
          </Panel>
        </div>
      </div>

      {/* ── Status bar ── */}
      <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between',
        padding:'5px 16px', borderTop:'1px solid rgba(255,255,255,0.06)',
        background:'rgba(6,8,20,0.9)', flexShrink:0 }}>
        <div style={{ display:'flex', gap:20 }}>
          {[
            { l:'Total',      v:stats.total },
            { l:'Avg Battery',v:`${stats.avgBattery}%` },
            { l:'Passengers', v:stats.totalPassengers },
            { l:'Incidents',  v:incidents.length },
          ].map((m) => (
            <span key={m.l} style={{ fontSize:9, color:'#445566', fontFamily:'monospace' }}>
              {m.l}: <span style={{ color:'#8899aa' }}>{m.v}</span>
            </span>
          ))}
        </div>
        <div style={{ width:240 }}>
          <LatencyMeter latency={latency} connected={connected} />
        </div>
        <span style={{ fontSize:9, color:'#334455', fontFamily:'monospace' }}>
          📍 Bangalore EV Fleet v2.0
        </span>
      </div>
    </div>
  );
}
